class _BidHistorySection extends StatefulWidget{final String userId;const _BidHistorySection({required this.userId});@override State<_BidHistorySection> createState()=>_BidHistorySectionState();}
class _BidHistorySectionState extends State<_BidHistorySection> with SingleTickerProviderStateMixin{late TabController _tabController;final Map<String,String> _cache={};@override void initState(){super.initState();_tabController=TabController(length:2,vsync:this);}@override void dispose(){_tabController.dispose();super.dispose();}Future<String> _name(String id)async{if(_cache.containsKey(id))return _cache[id]!;try{final d=await FirebaseFirestore.instance.collection('auction_products').doc(id).get();if(d.exists){final n=(d.data()?['product_name']??'គ្មានឈ្មោះ').toString();return _cache[id]=n;}}catch(e){debugPrint('$e');}return _cache[id]='គ្មានឈ្មោះ';}@override Widget build(BuildContext c)=>Column(children:[Container(margin:const EdgeInsets.only(bottom:8),decoration:BoxDecoration(color:Colors.grey[200],borderRadius:BorderRadius.circular(12)),child:TabBar(controller:_tabController,indicator:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(10)),indicatorSize:TabBarIndicatorSize.tab,labelColor:Colors.blueAccent,unselectedLabelColor:Colors.grey[600],tabs:const[Tab(text:'ប្រវត្តិដេញថ្លៃ'),Tab(text:'ប្រវត្តិឈ្នះ')])),SizedBox(height:400,child:TabBarView(controller:_tabController,children:[_bids(),_wins()]))]);Widget _bids()=>StreamBuilder<QuerySnapshot>(stream:FirebaseFirestore.instance.collectionGroup('bids').where('bidder_id',isEqualTo:widget.userId).orderBy('bid_time',descending:true).limit(20).snapshots(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(!s.hasData||s.data!.docs.isEmpty)return _empty('មិនទាន់មានប្រវត្តិដេញថ្លៃ');return ListView.builder(itemCount:s.data!.docs.length,itemBuilder:(c,i){final d=s.data!.docs[i];return _bid(d.data()as Map<String,dynamic>,d.reference.parent.parent?.id??'');});});Widget _wins()=>StreamBuilder<QuerySnapshot>(stream:FirebaseFirestore.instance.collection('auction_products').where('last_bidder_id',isEqualTo:widget.userId).snapshots(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(!s.hasData||s.data!.docs.isEmpty)return _empty('មិនទាន់មានប្រវត្តិឈ្នះ');return ListView.builder(itemCount:s.data!.docs.length,itemBuilder:(c,i){final d=s.data!.docs[i].data()as Map<String,dynamic>;final end=d['end_time'];return ListTile(leading:const Icon(Icons.emoji_events,color:Colors.amber),title:Text((d['product_name']??'គ្មានឈ្មោះ').toString()),subtitle:end is Timestamp?Text('បញ្ចប់៖ ${DateFormat('dd/MM/yyyy').format(end.toDate())}'):null,trailing:Text('${NumberFormat('#,###').format(d['current_price']??0)} ៛',style:const TextStyle(color:Colors.green,fontWeight:FontWeight.bold)));});});Widget _bid(Map<String,dynamic>d,String id)=>FutureBuilder<String>(future:_name(id),builder:(c,n)=>ListTile(leading:const Icon(Icons.gavel,color:Colors.blueAccent),title:Text(n.data??'កំពុងផ្ទុក...'),subtitle:d['bid_time']is Timestamp?Text(DateFormat('dd/MM/yyyy HH:mm').format((d['bid_time']as Timestamp).toDate())):null,trailing:Text('${NumberFormat('#,###').format(d['bid_amount']??0)} ៛',style:const TextStyle(color:Colors.green,fontWeight:FontWeight.bold))));Widget _empty(String m)=>_InfoCard(children:[Padding(padding:const EdgeInsets.all(24),child:Column(children:[const Icon(Icons.gavel_outlined,color:Colors.grey,size:40),const SizedBox(height:8),Text(m,style:const TextStyle(color:Colors.grey,fontFamily:'Siemreap'))]))]);}
